    ('c8eb92e3-2b50-5435-94f9-1d1bdd76a2b2'::uuid, 'Quiz — Dérive, sélection, spéciation', 'SVT', '2de', 'La biodiversité et son évolution dans le temps', '9486b614-17e8-57d2-8f5f-609a2beaacda'::uuid),
    ('799d301e-ba46-5547-b9cd-294ce7bacf61'::uuid, 'Quiz — Une sixième crise, et ce qui la distingue des cinq autres', 'SVT', '2de', 'Variation naturelle et impact humain', '57d9c600-626e-58ca-b0fc-c1ec860fb952'::uuid),
    ('78bf581b-a727-5283-bf91-ef4827d7c10c'::uuid, 'Quiz — Séduire, dissuader, coordonner', 'SVT', '2de', 'Communication intraspécifique et sélection sexuelle', '32d03172-b876-55bd-975e-14bad25823f4'::uuid),
    ('39a500b4-e29e-5c93-ac96-e58e65448373'::uuid, 'Quiz — Comment une montagne finit en grains de sable', 'SVT', '2de', 'L’érosion, phénomène naturel et inexorable', 'e382b2d4-1084-5430-860c-88f96e5c4759'::uuid),
