    ('3640ea91-cc66-5d1c-93bf-4b9e671e9fff'::uuid, 'Quiz — Le sol, une ressource vivante et lente', 'SVT', '2de', 'L’agriculture, la biomasse végétale et les sols', '5ca7b993-de65-51d0-9efc-24c5754bccc8'::uuid),
    ('d91bf192-a11e-55d4-a213-d8f5750c6248'::uuid, 'Quiz — Ce que coûte, en surface et en énergie, une assiette', 'SVT', '2de', 'Une agriculture pour nourrir les hommes', 'bd11366c-b2f6-595d-be9a-df309fa986dc'::uuid),
    ('8ec80c4b-185d-545a-be76-1047d0c9521a'::uuid, 'Quiz — Augmenter les rendements sans détruire ce qui les permet', 'SVT', '2de', 'Amélioration des rendements agricoles, santé et environnement', '48606f90-d322-5d1f-96fe-0bae83baf216'::uuid),
    ('2e7f5e18-78b6-5ca4-9eba-2a144173a1aa'::uuid, 'Quiz — Devenir un individu sexué, en trois temps', 'SVT', '2de', 'De la fécondation à la puberté', '2c93ca76-5144-5f8d-ba89-dc8a63675b64'::uuid),
    ('dbecdf2f-8460-5177-a510-e378bccab3cb'::uuid, 'Quiz — Deux niveaux de contrôle : réflexes et cerveau', 'SVT', '2de', 'Le système nerveux et la sexualité', 'e3f9a2bf-916c-5ad0-b50c-7249f2d1b3c2'::uuid),
    ('54e33e84-6d7e-56cf-b5f1-7520fafc6879'::uuid, 'Quiz — Un dialogue permanent entre le cerveau et les gonades', 'SVT', '2de', 'Le rôle des hormones dans la reproduction', '50f24365-e959-59d4-82ed-190b089b1b63'::uuid),
    ('d88d1901-226d-5075-ac92-f6299d98cb7f'::uuid, 'Quiz — Qui rend malade, et comment le microbe voyage', 'SVT', '2de', 'Agents pathogènes et maladies à vecteur', 'b0a679c3-f9e3-588d-995b-509660ddf51c'::uuid),
    ('c83a4d28-2012-58c5-b0eb-a9f050ea8d42'::uuid, 'Quiz — Vivre avec des milliards de partenaires', 'SVT', '2de', 'Symbiose et microbiote humain', 'a2d29333-a74e-5da5-92c3-4aa6d9248a7a'::uuid),
    ('a999ff85-31c2-5491-bda6-0aeac20bd271'::uuid, 'Quiz — Un organe à part entière', 'SVT', '2de', 'Microbiote intestinal et santé', 'ea7dca0a-3d18-5bd2-b02f-28363902dc9a'::uuid)
  ) AS v(id, title, subject, grade_level, chapter, lesson_id)
  JOIN public.lessons l ON l.id = v.lesson_id
 WHERE NOT EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.lesson_id = l.id)
ON CONFLICT (id) DO NOTHING;

-- 4. Questions -------------------------------------------------------------
INSERT INTO public.quiz_questions (id, quiz_id, question, kind, options, correct_index, explanation, position)
SELECT v.id, v.quiz_id, v.question, v.kind, v.options, v.correct_index, v.explanation, v.position
  FROM (VALUES
    ('9fd0d0ee-267a-5308-be1c-41b22ff67959'::uuid, '5ead8d8a-d215-5822-abd6-7418b94dc853'::uuid, 'Quel élément est commun à toutes les cellules ?', 'mcq', '["Une membrane plasmique, du cytoplasme et de l’ADN","Un noyau","Des chloroplastes","Une paroi"]'::jsonb, 0, 'Le noyau n’existe que chez les eucaryotes.', 1),
    ('34949632-58ab-5a60-9c71-fc664fd23ec6'::uuid, '5ead8d8a-d215-5822-abd6-7418b94dc853'::uuid, 'Qu’est-ce qui distingue une cellule procaryote d’une cellule eucaryote ?', 'mcq', '["L’absence de noyau chez la procaryote","L’absence de membrane chez la procaryote","L’absence d’ADN chez la procaryote","La présence de chloroplastes chez la procaryote"]'::jsonb, 0, 'Les bactéries sont des procaryotes.', 2),
    ('a0b9a73f-e2e4-56c8-9bcd-0e79e3f68ebb'::uuid, '5ead8d8a-d215-5822-abd6-7418b94dc853'::uuid, 'Quel ordre de grandeur pour une cellule animale ?', 'mcq', '["De 10 à 100 micromètres","De 1 à 10 nanomètres","De 1 à 5 millimètres","Environ 1 centimètre"]'::jsonb, 0, 'Une bactérie ne mesure que quelques micromètres.', 3),
    ('5c6cfa2c-992a-54c2-ae42-231a319dda0d'::uuid, '5ead8d8a-d215-5822-abd6-7418b94dc853'::uuid, 'Les cellules d’un même organisme pluricellulaire ont-elles le même génome ?', 'mcq', '["Oui, elles proviennent toutes de la cellule-œuf","Non, chacune a un génome propre","Seules les cellules du même organe","Seulement les cellules sexuelles"]'::jsonb, 0, 'Ce sont les gènes exprimés qui diffèrent.', 4),
    ('d3de2712-cc32-5934-bdee-89d149958a41'::uuid, '5ead8d8a-d215-5822-abd6-7418b94dc853'::uuid, 'Qu’est-ce que la différenciation cellulaire ?', 'mcq', '["L’acquisition d’une structure et d’une fonction spécialisées par expression d’une partie des gènes","La multiplication des cellules","La mort programmée des cellules","Le transfert d’ADN entre cellules"]'::jsonb, 0, 'Même génome, expressions différentes.', 5),
    ('d71dcae9-90ac-5250-b02d-e41ca062f42d'::uuid, '5ead8d8a-d215-5822-abd6-7418b94dc853'::uuid, 'Pourquoi le globule rouge humain est-il dépourvu de noyau ?', 'mcq', '["Pour maximiser la place disponible pour l’hémoglobine","Parce qu’il n’a pas d’ADN à l’origine","Parce qu’il ne respire pas","Parce qu’il est une bactérie"]'::jsonb, 0, 'Sa forme sert sa fonction de transport du dioxygène.', 6),
    ('e08de223-16f8-57e7-9733-0457adfd4662'::uuid, '5ead8d8a-d215-5822-abd6-7418b94dc853'::uuid, 'Un ensemble de cellules spécialisées de même type forme un organe.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il forme un tissu ; plusieurs tissus forment un organe.', 7),
    ('c6b239cd-fca5-5490-b7a8-ec1a5f1f0672'::uuid, '5ead8d8a-d215-5822-abd6-7418b94dc853'::uuid, 'Quel microscope permet d’observer les organites comme les mitochondries ?', 'mcq', '["Le microscope électronique","Le microscope optique","La loupe binoculaire","Le télescope"]'::jsonb, 0, 'Sa résolution est bien supérieure à celle du microscope optique.', 8),
    ('3f0c6466-628d-5a19-b4e3-03c14142ff77'::uuid, '9ea0c73c-393a-5e62-8ed0-616ffae40a38'::uuid, 'Qu’est-ce que le métabolisme d’une cellule ?', 'mcq', '["L’ensemble des réactions chimiques qui s’y déroulent","Sa vitesse de division","Sa taille et sa forme","Son mode de déplacement"]'::jsonb, 0, 'Il assure production de matière et fourniture d’énergie.', 1),
    ('a1356e39-67ed-57c5-b01c-8daeb7062ec4'::uuid, '9ea0c73c-393a-5e62-8ed0-616ffae40a38'::uuid, 'Qu’est-ce qu’une cellule autotrophe ?', 'mcq', '["Une cellule qui produit sa matière organique à partir de matière minérale","Une cellule qui se nourrit d’autres cellules","Une cellule sans noyau","Une cellule qui ne respire pas"]'::jsonb, 0, 'Les cellules chlorophylliennes en sont l’exemple type.', 2),
    ('313c66c4-a22e-59c2-87ef-f5dee98c1ca7'::uuid, '9ea0c73c-393a-5e62-8ed0-616ffae40a38'::uuid, 'Dans quel organite se déroule la photosynthèse ?', 'mcq', '["Le chloroplaste","La mitochondrie","Le noyau","Le réticulum"]'::jsonb, 0, 'Il contient la chlorophylle qui capte l’énergie lumineuse.', 3),
    ('e7f928d7-0bb6-5803-884a-972afef8e2de'::uuid, '9ea0c73c-393a-5e62-8ed0-616ffae40a38'::uuid, 'Que produit la photosynthèse ?', 'mcq', '["Du glucose et du dioxygène","Du dioxyde de carbone et de l’eau","De l’éthanol","De l’acide lactique"]'::jsonb, 0, 'À partir de CO2, d’eau et d’énergie lumineuse.', 4),
    ('3013abba-500d-5a88-8a19-a758ba60d63a'::uuid, '9ea0c73c-393a-5e62-8ed0-616ffae40a38'::uuid, 'Où se déroule la respiration cellulaire ?', 'mcq', '["Dans les mitochondries","Dans les chloroplastes","Dans le noyau","Dans la membrane plasmique"]'::jsonb, 0, 'Elle dégrade complètement le glucose en présence de dioxygène.', 5),
    ('91bef9bf-170f-57c0-b349-bb49cda44131'::uuid, '9ea0c73c-393a-5e62-8ed0-616ffae40a38'::uuid, 'Quelle différence énergétique entre respiration et fermentation ?', 'mcq', '["La respiration libère beaucoup plus d’énergie","La fermentation libère plus d’énergie","Les deux libèrent autant d’énergie","La fermentation ne libère aucune énergie"]'::jsonb, 0, 'Mais la fermentation permet de survivre sans dioxygène.', 6),
    ('c8abcd89-31a4-50c4-a1d1-8528366057be'::uuid, '9ea0c73c-393a-5e62-8ed0-616ffae40a38'::uuid, 'Le métabolisme d’une cellule dépend uniquement de son patrimoine génétique.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il dépend aussi de son environnement : lumière, dioxygène, nutriments.', 7),
    ('20054050-9339-5b1f-89b5-fc0c4246e4db'::uuid, '9ea0c73c-393a-5e62-8ed0-616ffae40a38'::uuid, 'Quel est le rôle d’une enzyme ?', 'mcq', '["Catalyser une réaction chimique de façon spécifique","Transporter le dioxygène","Stocker l’information génétique","Constituer la membrane"]'::jsonb, 0, 'Sans le gène de l’enzyme, la réaction n’est pas réalisable.', 8),
    ('c993fcb8-e1eb-5e69-8772-bce7bd08f009'::uuid, 'c2b729be-5899-5f60-abbe-59b657132454'::uuid, 'À quelles trois échelles la biodiversité se mesure-t-elle ?', 'mcq', '["Écosystèmes, espèces, diversité génétique","Continents, pays, régions","Cellules, tissus, organes","Passé, présent, futur"]'::jsonb, 0, 'Ces trois niveaux sont emboîtés.', 1),
    ('2ab9ec86-1462-5ad6-9682-075d78eff2a9'::uuid, 'c2b729be-5899-5f60-abbe-59b657132454'::uuid, 'Que désigne la biosphère ?', 'mcq', '["L’ensemble des êtres vivants et des milieux qu’ils occupent","La couche d’ozone","Les océans uniquement","La partie solide de la Terre"]'::jsonb, 0, 'Elle n’occupe qu’une fine pellicule à l’échelle du globe.', 2),
    ('8638db12-cb1d-5f85-b110-45503c27864f'::uuid, 'c2b729be-5899-5f60-abbe-59b657132454'::uuid, 'De quoi un écosystème est-il constitué ?', 'mcq', '["D’un biotope et d’une biocénose","De producteurs uniquement","D’un sol et d’un climat","D’espèces sans interactions"]'::jsonb, 0, 'Le milieu physique et l’ensemble des vivants en relation.', 3),
    ('a26dab88-14fe-56b2-a802-c527793e8a18'::uuid, 'c2b729be-5899-5f60-abbe-59b657132454'::uuid, 'Quel rôle jouent les décomposeurs ?', 'mcq', '["Ils reminéralisent la matière organique morte","Ils produisent la matière organique","Ils consomment les producteurs primaires","Ils fixent l’énergie lumineuse"]'::jsonb, 0, 'Ils referment les cycles de matière.', 4),
    ('4d9b7e06-de80-58ec-a0bb-f0c88d72ecda'::uuid, 'c2b729be-5899-5f60-abbe-59b657132454'::uuid, 'Par où l’énergie entre-t-elle principalement dans un écosystème ?', 'mcq', '["Par la photosynthèse des producteurs primaires","Par la respiration des animaux","Par les décomposeurs","Par les précipitations"]'::jsonb, 0, 'Elle est ensuite transmise puis dissipée.', 5),
    ('4b1abb09-1ea3-5a14-8e57-737be35fe7f8'::uuid, 'c2b729be-5899-5f60-abbe-59b657132454'::uuid, 'Combien de crises biologiques majeures l’histoire de la vie compte-t-elle ?', 'mcq', '["Cinq","Deux","Dix","Aucune"]'::jsonb, 0, 'La plus connue marque la limite Crétacé-Paléogène.', 6),
    ('fb67490b-4bce-5184-912b-bdbaffb77a9a'::uuid, 'c2b729be-5899-5f60-abbe-59b657132454'::uuid, 'Il y a combien de millions d’années la crise Crétacé-Paléogène s’est-elle produite ?', 'mcq', '["66 millions d’années","250 millions d’années","10 millions d’années","541 millions d’années"]'::jsonb, 0, 'Elle a notamment vu disparaître les dinosaures non aviens.', 7),
    ('23aef59e-2027-5e98-b9a1-bf48e407aef8'::uuid, 'c2b729be-5899-5f60-abbe-59b657132454'::uuid, 'La biodiversité actuelle est l’aboutissement définitif de l’évolution.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle en est un état, qui continue de changer.', 8),
    ('67394d16-4217-5ed8-9041-da31208cf6df'::uuid, '0eeb0a43-8eef-5a91-9383-c17006c17785'::uuid, 'Quelle différence entre un gène et un allèle ?', 'mcq', '["Le gène est la séquence, l’allèle en est une version particulière","Le gène est une protéine, l’allèle un chromosome","Ce sont deux mots synonymes","L’allèle est plus long que le gène"]'::jsonb, 0, 'Deux individus partagent les gènes, mais pas forcément les allèles.', 1),
    ('38770bbb-3251-579b-b482-a8f129e34664'::uuid, '0eeb0a43-8eef-5a91-9383-c17006c17785'::uuid, 'Quelle est la source première de nouveaux allèles ?', 'mcq', '["La mutation","La méiose","La fécondation","La respiration cellulaire"]'::jsonb, 0, 'Elle modifie aléatoirement la séquence de l’ADN.', 2),
    ('e7fae7c8-0754-596f-a883-020d35b64273'::uuid, '0eeb0a43-8eef-5a91-9383-c17006c17785'::uuid, 'Qu’est-ce qu’un agent mutagène ?', 'mcq', '["Un facteur qui augmente la fréquence des mutations","Une enzyme de réparation","Un allèle dominant","Un chromosome supplémentaire"]'::jsonb, 0, 'Les UV, les rayons X et certaines substances chimiques en sont.', 3),
    ('b7ebf2f0-dc7e-5e6a-9de9-2f48a47aac77'::uuid, '0eeb0a43-8eef-5a91-9383-c17006c17785'::uuid, 'Que produit le brassage interchromosomique ?', 'mcq', '["Une répartition indépendante des chromosomes de chaque paire dans les gamètes","Un échange de segments entre chromosomes homologues","La fusion de deux gamètes","Une duplication du génome"]'::jsonb, 0, 'Le brassage intrachromosomique, lui, correspond au crossing-over.', 4),
    ('e1ad7fa2-6b25-5ebf-aeb9-7398fc842271'::uuid, '0eeb0a43-8eef-5a91-9383-c17006c17785'::uuid, 'Combien de combinaisons produit le seul brassage interchromosomique chez l’humain ?', 'mcq', '["Plus de 8 millions","Environ 200","Environ 46","Environ 1 000"]'::jsonb, 0, 'Soit 2 puissance 23, avant crossing-over et fécondation.', 5),
    ('c2beb9c9-af5a-5b27-87c5-fa90f2ff0389'::uuid, '0eeb0a43-8eef-5a91-9383-c17006c17785'::uuid, 'À quel moment se produit la réunion au hasard de deux gamètes ?', 'mcq', '["À la fécondation","À la méiose","À la mitose","À la naissance"]'::jsonb, 0, 'Elle multiplie encore le nombre de combinaisons possibles.', 6),
    ('dee34c05-8a9b-5d2c-b7d8-5cfe26810311'::uuid, '0eeb0a43-8eef-5a91-9383-c17006c17785'::uuid, 'La plupart des mutations sont avantageuses pour l’individu.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La plupart sont sans effet, certaines défavorables, peu sont avantageuses.', 7),
    ('6610dc89-3e5a-5ee3-b9f9-f707cbde5c7b'::uuid, '0eeb0a43-8eef-5a91-9383-c17006c17785'::uuid, 'Pourquoi une population génétiquement diverse est-elle plus robuste ?', 'mcq', '["Parce qu’il est plus probable que certains individus portent un allèle avantageux","Parce qu’elle se reproduit plus vite","Parce qu’elle mute davantage","Parce qu’elle occupe un territoire plus grand"]'::jsonb, 0, 'Une population peu diverse est fragile face aux changements.', 8),
    ('1db5801b-a492-5fac-9e5e-588e4da88bb1'::uuid, 'c8eb92e3-2b50-5435-94f9-1d1bdd76a2b2'::uuid, 'Qu’est-ce que la dérive génétique ?', 'mcq', '["Une modification aléatoire de la fréquence des allèles au fil des générations","Le tri des individus les mieux adaptés","L’apparition de nouveaux allèles","Le déplacement d’une population"]'::jsonb, 0, 'Elle agit d’autant plus fort que la population est petite.', 1),
    ('ea1adba6-2488-50a8-a6bb-9defed075a19'::uuid, 'c8eb92e3-2b50-5435-94f9-1d1bdd76a2b2'::uuid, 'Dans quel type de population l’effet de la dérive est-il le plus marqué ?', 'mcq', '["Une population de petit effectif","Une population de grand effectif","Une population en croissance","Une population migratrice"]'::jsonb, 0, 'Dans un grand effectif, les écarts aléatoires s’annulent.', 2),
    ('eb4a55bb-4d25-5cb7-a591-b1b6de55b2fb'::uuid, 'c8eb92e3-2b50-5435-94f9-1d1bdd76a2b2'::uuid, 'La sélection naturelle est-elle un processus aléatoire ?', 'mcq', '["Non, elle trie selon l’avantage conféré dans un environnement donné","Oui, entièrement","Oui, comme la dérive","Elle ne concerne que les plantes"]'::jsonb, 0, 'Le hasard intervient dans la mutation, pas dans le tri.', 3),
    ('c4a06c1b-ca31-54b1-af34-d7069d76b414'::uuid, 'c8eb92e3-2b50-5435-94f9-1d1bdd76a2b2'::uuid, 'Que montre l’exemple de la phalène du bouleau ?', 'mcq', '["Un changement de fréquence des formes selon la pollution des troncs","L’apparition d’une nouvelle espèce","Un effet de dérive génétique","Une mutation provoquée par la suie"]'::jsonb, 0, 'La forme sombre a été favorisée quand les troncs ont noirci.', 4),
    ('653a4421-658e-52b8-9c02-13c4ece0c499'::uuid, 'c8eb92e3-2b50-5435-94f9-1d1bdd76a2b2'::uuid, 'La sélection naturelle crée-t-elle de nouveaux allèles ?', 'mcq', '["Non, elle trie ceux produits par la mutation","Oui, en réponse au besoin","Oui, à chaque génération","Seulement chez les bactéries"]'::jsonb, 0, 'C’est une distinction essentielle du raisonnement évolutif.', 5),
    ('e60c62ab-c2d8-5cad-b42e-4c863198f00b'::uuid, 'c8eb92e3-2b50-5435-94f9-1d1bdd76a2b2'::uuid, 'Qu’est-ce que la spéciation ?', 'mcq', '["L’apparition de nouvelles espèces à partir de populations isolées","La disparition d’une espèce","Le croisement de deux espèces","La classification des espèces"]'::jsonb, 0, 'L’isolement permet l’accumulation de différences génétiques.', 6),
    ('1d8e3686-334b-5f30-9c1d-7abbbf606eb1'::uuid, 'c8eb92e3-2b50-5435-94f9-1d1bdd76a2b2'::uuid, 'Quelle définition courante de l’espèce est utilisée en seconde ?', 'mcq', '["Un ensemble d’individus interféconds dont la descendance est fertile","Un ensemble d’individus vivant au même endroit","Un ensemble d’individus de même taille","Un ensemble d’individus au même génome"]'::jsonb, 0, 'Elle connaît de nombreux cas limites.', 7),
    ('43cbb6d5-c1ce-5ac8-8076-b4bc0bacc7c0'::uuid, 'c8eb92e3-2b50-5435-94f9-1d1bdd76a2b2'::uuid, 'La notion d’espèce s’applique sans difficulté aux fossiles et aux bactéries.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ni les fossiles ni la reproduction asexuée n’entrent dans le critère d’interfécondité.', 8),
    ('8ec16f81-f564-53e4-a1f1-971b872b5aeb'::uuid, '799d301e-ba46-5547-b9cd-294ce7bacf61'::uuid, 'Quelles causes expliquent les crises biologiques passées ?', 'mcq', '["Volcanisme, impact d’astéroïde, changements climatiques majeurs","L’activité humaine","Les épidémies uniquement","La dérive génétique"]'::jsonb, 0, 'Elles sont géologiques ou astronomiques.', 1),
    ('f7145c71-7cfc-52b1-9e8c-de8226eb8ee0'::uuid, '799d301e-ba46-5547-b9cd-294ce7bacf61'::uuid, 'Qu’est-ce qu’une radiation évolutive après une crise ?', 'mcq', '["La diversification rapide des groupes survivants","L’extinction totale d’un groupe","L’émission de rayonnements","Le retour des espèces disparues"]'::jsonb, 0, 'Les niches libérées sont réoccupées.', 2),
    ('f5f63307-71cb-55e1-9f3a-4a92efdf19bb'::uuid, '799d301e-ba46-5547-b9cd-294ce7bacf61'::uuid, 'Comment se situe le taux d’extinction actuel par rapport à la moyenne des archives fossiles ?', 'mcq', '["De 10 à 100 fois supérieur","Équivalent","Deux fois inférieur","Impossible à estimer"]'::jsonb, 0, 'D’où l’expression de sixième crise biologique.', 3),
    ('71537193-95ee-5d2a-bee8-0b4aac75f1c3'::uuid, '799d301e-ba46-5547-b9cd-294ce7bacf61'::uuid, 'Quelle est la première cause d’érosion actuelle de la biodiversité ?', 'mcq', '["La destruction et la fragmentation des habitats","Le changement climatique","Les espèces envahissantes","Les pollutions lumineuses"]'::jsonb, 0, 'Le changement climatique est une cause dont le poids augmente.', 4),
    ('edf336d0-3e9b-58cf-9e5d-766c740ab694'::uuid, '799d301e-ba46-5547-b9cd-294ce7bacf61'::uuid, 'Qu’est-ce qu’une espèce exotique envahissante ?', 'mcq', '["Une espèce introduite hors de son aire d’origine qui s’y développe au détriment des espèces locales","Une espèce protégée","Une espèce migratrice","Une espèce en danger"]'::jsonb, 0, 'C’est l’une des cinq grandes causes identifiées.', 5),
    ('efbaf1c9-d534-5908-87e5-53db9aa32881'::uuid, '799d301e-ba46-5547-b9cd-294ce7bacf61'::uuid, 'Que classent les listes rouges de l’UICN ?', 'mcq', '["Les espèces selon leur risque d’extinction","Les zones protégées","Les pollutions industrielles","Les espèces introduites"]'::jsonb, 0, 'Elles servent d’indicateur international.', 6),
    ('109aeafa-1bdc-58bc-a20f-a7ca17870c7d'::uuid, '799d301e-ba46-5547-b9cd-294ce7bacf61'::uuid, 'À quoi sert un corridor écologique ?', 'mcq', '["Relier des habitats fragmentés pour permettre la circulation des espèces","Interdire l’accès à une réserve","Canaliser un cours d’eau","Séparer deux populations"]'::jsonb, 0, 'La fragmentation isole les populations et les fragilise.', 7),
    ('11e55b6d-a36f-5c40-96a1-0c135eef5bf1'::uuid, '799d301e-ba46-5547-b9cd-294ce7bacf61'::uuid, 'La sixième crise se distingue des précédentes par son origine humaine.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Et par sa vitesse, très supérieure au rythme naturel.', 8),
    ('c1c1ea14-eaf0-574d-9d61-da8c86e534ef'::uuid, '78bf581b-a727-5283-bf91-ef4827d7c10c'::uuid, 'Qu’est-ce qu’une phéromone ?', 'mcq', '["Une molécule émise par un individu qui modifie le comportement d’un congénère","Une hormone circulant dans le sang","Un signal sonore de basse fréquence","Un pigment de la peau"]'::jsonb, 0, 'Elle agit à très faible concentration, parfois à grande distance.', 1),
    ('2d8a5462-d1b3-528e-8bd9-5b379d79f68e'::uuid, '78bf581b-a727-5283-bf91-ef4827d7c10c'::uuid, 'Quel avantage présente la communication sonore ?', 'mcq', '["Elle porte loin et fonctionne de nuit","Elle est indétectable par les prédateurs","Elle ne coûte aucune énergie","Elle est propre aux insectes"]'::jsonb, 0, 'Chants d’oiseaux, stridulations, coassements.', 2),
    ('82236124-37d1-58ee-8031-3ac09527c1d7'::uuid, '78bf581b-a727-5283-bf91-ef4827d7c10c'::uuid, 'Quelles sont les trois grandes fonctions des signaux intraspécifiques ?', 'mcq', '["Reproduction, compétition, cohésion sociale","Nutrition, respiration, excrétion","Croissance, mue, migration","Défense, camouflage, fuite"]'::jsonb, 0, 'Un même signal peut en servir plusieurs.', 3),
    ('bf23a15b-32fa-5c25-820a-604d76577348'::uuid, '78bf581b-a727-5283-bf91-ef4827d7c10c'::uuid, 'Pourquoi un signal coûteux est-il une information fiable ?', 'mcq', '["Parce qu’un individu en mauvais état ne peut pas le produire","Parce qu’il est rare","Parce qu’il est silencieux","Parce qu’il est appris"]'::jsonb, 0, 'Le coût rend le signal difficile à truquer.', 4),
    ('864998ab-6a8f-563f-8c1a-a898fef491b9'::uuid, '78bf581b-a727-5283-bf91-ef4827d7c10c'::uuid, 'Qui a décrit la sélection sexuelle ?', 'mcq', '["Charles Darwin","Gregor Mendel","Jean-Baptiste de Lamarck","Louis Pasteur"]'::jsonb, 0, 'Elle complète sa théorie de la sélection naturelle.', 5),
    ('0bb70670-efd4-5cca-afa4-37c802b9b330'::uuid, '78bf581b-a727-5283-bf91-ef4827d7c10c'::uuid, 'Quelle est la différence entre compétition intrasexuelle et choix intersexuel ?', 'mcq', '["L’une oppose des individus du même sexe, l’autre repose sur le choix du partenaire","L’une concerne les plantes, l’autre les animaux","L’une est génétique, l’autre comportementale","Il n’y a pas de différence"]'::jsonb, 0, 'Combats de cerfs d’un côté, choix des femelles de l’autre.', 6),
    ('4a95e5d8-3f54-5a26-a811-aafa063b8aed'::uuid, '78bf581b-a727-5283-bf91-ef4827d7c10c'::uuid, 'Pourquoi la queue du paon persiste-t-elle malgré son coût ?', 'mcq', '["Parce que le gain en succès reproducteur compense la perte de survie","Parce qu’elle protège des prédateurs","Parce qu’elle facilite le vol","Parce qu’elle est neutre pour la survie"]'::jsonb, 0, 'C’est le paradoxe classique de la sélection sexuelle.', 7),
    ('88b2dacf-7296-5985-8a6e-ebba869147b5'::uuid, '78bf581b-a727-5283-bf91-ef4827d7c10c'::uuid, 'La sélection sexuelle favorise toujours des caractères qui améliorent la survie.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle peut favoriser des caractères coûteux en survie.', 8),
    ('3ea1527d-6058-582c-b221-651f0a6b2894'::uuid, '39a500b4-e29e-5c93-ac96-e58e65448373'::uuid, 'Quelles sont les trois étapes de l’érosion ?', 'mcq', '["Altération, ablation, transport","Dépôt, compaction, cimentation","Fusion, cristallisation, refroidissement","Pluie, ruissellement, infiltration"]'::jsonb, 0, 'Le dépôt relève ensuite de la sédimentation.', 1),
    ('274ff721-1907-51d9-b200-d33d5e6f2eac'::uuid, '39a500b4-e29e-5c93-ac96-e58e65448373'::uuid, 'Qu’est-ce que la gélifraction ?', 'mcq', '["L’éclatement d’une roche par le gel de l’eau dans ses fissures","La dissolution du calcaire","L’usure par le vent","La transformation du feldspath en argile"]'::jsonb, 0, 'L’eau qui gèle augmente de volume.', 2),
    ('9080f361-2bed-5a12-8384-97174b42b55b'::uuid, '39a500b4-e29e-5c93-ac96-e58e65448373'::uuid, 'Quel type de paysage résulte de la dissolution du calcaire ?', 'mcq', '["Un paysage karstique","Une arène granitique","Un delta","Une moraine"]'::jsonb, 0, 'Grottes, gouffres, lapiaz et résurgences.', 3),
    ('07075e84-1a18-5f56-8ee8-ff71a60d911a'::uuid, '39a500b4-e29e-5c93-ac96-e58e65448373'::uuid, 'En quoi se transforme le feldspath du granite lors de l’hydrolyse ?', 'mcq', '["En argile","En quartz","En calcaire","En sel"]'::jsonb, 0, 'Le quartz, lui, résiste et subsiste en grains.', 4),
    ('42521ba8-244a-50ed-ba4d-47b1bc51c31f'::uuid, '39a500b4-e29e-5c93-ac96-e58e65448373'::uuid, 'Comment appelle-t-on le sable issu de la désagrégation d’un granite sur place ?', 'mcq', '["L’arène granitique","Le lœss","La marne","Le gneiss"]'::jsonb, 0, 'Elle est composée surtout de quartz et d’argiles.', 5),
    ('ecbc7ea0-4003-571b-ab96-c1a48b94a69f'::uuid, '39a500b4-e29e-5c93-ac96-e58e65448373'::uuid, 'Que devient un grain transporté longtemps par une rivière ?', 'mcq', '["Il s’arrondit et se trie par taille","Il devient anguleux","Il grossit","Il se dissout entièrement"]'::jsonb, 0, 'La forme du grain renseigne sur la distance parcourue.', 6),
    ('0531b24a-60a5-5f4f-85b6-40164d24a7d7'::uuid, '39a500b4-e29e-5c93-ac96-e58e65448373'::uuid, 'Quel climat favorise le plus l’altération chimique ?', 'mcq', '["Un climat chaud et humide","Un climat froid et sec","Un climat désertique","Un climat polaire"]'::jsonb, 0, 'Le gel favorise plutôt l’altération physique.', 7),
    ('18611c8e-cce7-5e61-bc88-26338cbe3a28'::uuid, '39a500b4-e29e-5c93-ac96-e58e65448373'::uuid, 'La végétation accélère l’érosion des sols.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle la freine en retenant les particules avec ses racines.', 8),
    ('5568f8ce-8843-5ba3-b875-2c8de7f73373'::uuid, '3e0c785f-9c7a-585c-b3a6-d5ff4737b410'::uuid, 'Quand un sédiment se dépose-t-il ?', 'mcq', '["Quand l’agent de transport perd de l’énergie","Quand la température augmente","Quand la pression diminue","Quand le vent se lève"]'::jsonb, 0, 'Les gros éléments se déposent en premier.', 1),
    ('2d5c8119-d072-500c-8faf-a9f8a1b07974'::uuid, '3e0c785f-9c7a-585c-b3a6-d5ff4737b410'::uuid, 'Qu’est-ce que le tri granulométrique ?', 'mcq', '["Le classement des dépôts selon la taille des grains","La séparation des minéraux par densité","La mesure de la porosité","Le comptage des fossiles"]'::jsonb, 0, 'Blocs en amont, argiles en eau calme.', 2),
    ('5ff3be88-f92c-5145-a420-0ebed87b2f98'::uuid, '3e0c785f-9c7a-585c-b3a6-d5ff4737b410'::uuid, 'Quelles sont les deux étapes de la diagenèse ?', 'mcq', '["La compaction et la cimentation","La fusion et la cristallisation","L’altération et l’ablation","La dissolution et la précipitation"]'::jsonb, 0, 'Elles transforment un sédiment meuble en roche cohérente.', 3),
    ('a584318a-7a72-52dd-9653-ffd80f0b8785'::uuid, '3e0c785f-9c7a-585c-b3a6-d5ff4737b410'::uuid, 'En quelle roche le sable se transforme-t-il ?', 'mcq', '["Le grès","L’argilite","Le calcaire","Le granite"]'::jsonb, 0, 'L’argile donne, elle, une argilite.', 4),
    ('2df7d038-ac55-5cdb-9b4c-fdf211bf282b'::uuid, '3e0c785f-9c7a-585c-b3a6-d5ff4737b410'::uuid, 'À quelle famille appartient la craie ?', 'mcq', '["Aux roches biogènes","Aux roches détritiques","Aux roches magmatiques","Aux roches métamorphiques"]'::jsonb, 0, 'Elle est formée de squelettes microscopiques d’algues marines.', 5),
    ('cc4354bc-eb02-5e1f-a4d8-e4dc4df79124'::uuid, '3e0c785f-9c7a-585c-b3a6-d5ff4737b410'::uuid, 'Que dit le principe de superposition ?', 'mcq', '["Dans une série non déformée, les couches les plus anciennes sont en bas","Les couches les plus épaisses sont les plus anciennes","Les fossiles sont toujours au sommet","Les strates se déposent verticalement"]'::jsonb, 0, 'Il fonde la lecture chronologique des séries sédimentaires.', 6),
    ('8afe4ac5-7751-5da8-b422-3b9c278ca900'::uuid, '3e0c785f-9c7a-585c-b3a6-d5ff4737b410'::uuid, 'Le sel gemme est une roche détritique.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est une roche chimique, née de l’évaporation et de la précipitation.', 7),
    ('be4ed847-dfd3-55ae-a317-515b01c2b06f'::uuid, '3e0c785f-9c7a-585c-b3a6-d5ff4737b410'::uuid, 'Que peut devenir une roche sédimentaire enfouie très profondément ?', 'mcq', '["Une roche métamorphique, voire une roche magmatique si elle fond","Un sédiment meuble","Un fossile","Un sol"]'::jsonb, 0, 'Le cycle des roches boucle sur lui-même.', 8),
    ('c04fe0bf-c61f-5194-b8d1-f65863f777cf'::uuid, 'ab8c2b27-c70c-5344-8fba-6889acae11e9'::uuid, 'Quel risque lié à l’érosion menace directement le littoral ?', 'mcq', '["Le recul du trait de côte","Les séismes","Les éruptions volcaniques","Les tempêtes solaires"]'::jsonb, 0, 'Il conduit parfois à l’effondrement de falaises et d’habitations.', 1),
    ('ebb451c4-c5a4-556a-a64a-11ad25db941f'::uuid, 'ab8c2b27-c70c-5344-8fba-6889acae11e9'::uuid, 'Pourquoi la perte des sols agricoles est-elle grave ?', 'mcq', '["Parce qu’un sol met des siècles à se former","Parce que les sols sont radioactifs","Parce qu’ils sont rares en montagne","Parce qu’ils sont peu profonds partout"]'::jsonb, 0, 'Il peut partir en une seule saison de ruissellement.', 2),
    ('2ca7df80-7c81-5e0e-80f9-fb43377e2e1e'::uuid, 'ab8c2b27-c70c-5344-8fba-6889acae11e9'::uuid, 'À quoi servent principalement les granulats extraits ?', 'mcq', '["À fabriquer le béton","À produire de l’électricité","À fertiliser les cultures","À fabriquer du verre uniquement"]'::jsonb, 0, 'Sables et graviers sont la base des matériaux de construction.', 3),
    ('c7e223eb-e14d-54ce-8f9d-dc4a1cd112cd'::uuid, 'ab8c2b27-c70c-5344-8fba-6889acae11e9'::uuid, 'Quel est le rang du sable parmi les ressources les plus consommées au monde ?', 'mcq', '["Le deuxième, après l’eau","Le premier","Le cinquième","Le dixième"]'::jsonb, 0, 'Son extraction pose de graves problèmes environnementaux.', 4),
    ('a3668454-739e-5797-ac87-7034a47544c3'::uuid, 'ab8c2b27-c70c-5344-8fba-6889acae11e9'::uuid, 'Quel effet un barrage a-t-il sur les plages situées en aval ?', 'mcq', '["Il piège les sédiments et prive les plages de sable","Il augmente leur alimentation en sable","Il n’a aucun effet","Il élève le niveau de la mer"]'::jsonb, 0, 'Le recul du littoral s’en trouve accéléré.', 5),
    ('59f511af-d3fa-56f7-84ff-3a1103d088ae'::uuid, 'ab8c2b27-c70c-5344-8fba-6889acae11e9'::uuid, 'Quelle pratique agricole limite le ruissellement sur une pente ?', 'mcq', '["Labourer perpendiculairement à la pente","Labourer dans le sens de la pente","Retirer les haies","Laisser le sol nu en hiver"]'::jsonb, 0, 'Les bandes enherbées et les terrasses ont le même but.', 6),
    ('bfcc2834-5f44-5cd6-a0ef-434efe1c3c71'::uuid, 'ab8c2b27-c70c-5344-8fba-6889acae11e9'::uuid, 'L’imperméabilisation des sols urbains réduit le ruissellement.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle l’augmente fortement, l’eau ne pouvant plus s’infiltrer.', 7),
    ('8ccb4c3a-71c5-531a-a015-5dd665e6dc13'::uuid, 'ab8c2b27-c70c-5344-8fba-6889acae11e9'::uuid, 'Qu’appelle-t-on repli stratégique face à l’érosion côtière ?', 'mcq', '["Déplacer les constructions plutôt que défendre indéfiniment le rivage","Construire une digue plus haute","Interdire l’accès à la plage","Recharger la plage en sable chaque année"]'::jsonb, 0, 'C’est une décision politique autant que technique.', 8),
    ('c57d8cbc-5e8e-5ee8-91ef-3dc2758117e0'::uuid, '3640ea91-cc66-5d1c-93bf-4b9e671e9fff'::uuid, 'Qu’est-ce que la biomasse ?', 'mcq', '["La masse de matière organique produite par les êtres vivants","La masse de minéraux d’un sol","La quantité d’eau d’un écosystème","Le poids des engrais utilisés"]'::jsonb, 0, 'Les végétaux la produisent par photosynthèse.', 1),
    ('b8d8416d-c48d-52a8-8bed-c2165b654393'::uuid, '3640ea91-cc66-5d1c-93bf-4b9e671e9fff'::uuid, 'De quoi un sol est-il composé ?', 'mcq', '["De matière minérale, de matière organique, d’eau, d’air et d’organismes vivants","Uniquement de sable et d’argile","De roche mère non altérée","D’humus uniquement"]'::jsonb, 0, 'C’est un écosystème à part entière.', 2),
    ('fbfbfac3-3b6c-5205-afcd-330a96f84eec'::uuid, '3640ea91-cc66-5d1c-93bf-4b9e671e9fff'::uuid, 'Qu’est-ce que l’humus ?', 'mcq', '["La matière organique du sol issue de la décomposition","La couche de roche mère","Un engrais chimique","Une argile particulière"]'::jsonb, 0, 'Il joue un rôle majeur dans la fertilité.', 3),
    ('25eed9a2-1d16-5efb-9990-9efff23300cd'::uuid, '3640ea91-cc66-5d1c-93bf-4b9e671e9fff'::uuid, 'Combien de temps faut-il pour former un centimètre de sol ?', 'mcq', '["De plusieurs décennies à plusieurs siècles","Quelques mois","Environ dix ans","Quelques jours"]'::jsonb, 0, 'À l’échelle humaine, le sol n’est donc pas renouvelable.', 4),
    ('7432971e-7452-5dc7-9357-c39a376e81b6'::uuid, '3640ea91-cc66-5d1c-93bf-4b9e671e9fff'::uuid, 'Quels éléments minéraux sont les principaux facteurs limitants des cultures ?', 'mcq', '["L’azote, le phosphore et le potassium","Le carbone, l’hydrogène et l’oxygène","Le fer, le cuivre et le zinc","Le sodium et le chlore"]'::jsonb, 0, 'Ce sont les trois composants des engrais NPK.', 5),
    ('d8f2ac21-f332-5b1f-b484-cb1ce70793bf'::uuid, '3640ea91-cc66-5d1c-93bf-4b9e671e9fff'::uuid, 'Qu’est-ce que l’artificialisation des sols ?', 'mcq', '["Leur recouvrement par des constructions et des infrastructures","Leur enrichissement en engrais","Leur labour profond","Leur irrigation"]'::jsonb, 0, 'Elle retire définitivement des surfaces à l’agriculture.', 6),
    ('5c495318-9df5-5a95-bc89-28f2589af90a'::uuid, '3640ea91-cc66-5d1c-93bf-4b9e671e9fff'::uuid, 'Un sol est un support inerte pour les plantes.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Sa fertilité vient largement de son activité biologique.', 7),
    ('ad1f6468-e3f3-5625-b391-9a8207677837'::uuid, '3640ea91-cc66-5d1c-93bf-4b9e671e9fff'::uuid, 'Quelle pratique entretient la fertilité d’un sol ?', 'mcq', '["La rotation des cultures et la couverture permanente du sol","Le sol nu toute l’année","Le passage répété d’engins lourds","La monoculture continue"]'::jsonb, 0, 'Ces pratiques limitent érosion et perte de matière organique.', 8),
    ('193bbdd6-6250-5cd9-b9de-e8abc69c800a'::uuid, 'd91bf192-a11e-55d4-a213-d8f5750c6248'::uuid, 'Quelle part de l’énergie passe environ d’un maillon à l’autre d’une chaîne alimentaire ?', 'mcq', '["Environ 10 %","Environ 90 %","Environ 50 %","La totalité"]'::jsonb, 0, 'Le reste est dissipé par la respiration et les déchets.', 1),
    ('1805946d-d787-542d-bc50-9b2787a17510'::uuid, 'd91bf192-a11e-55d4-a213-d8f5750c6248'::uuid, 'Quelle conséquence en tire-t-on pour l’alimentation humaine ?', 'mcq', '["Produire des protéines animales demande beaucoup plus de surface que des protéines végétales","Les protéines animales sont plus économes en surface","La surface nécessaire est la même","L’énergie ne joue aucun rôle"]'::jsonb, 0, 'Le régime alimentaire a un effet direct sur la surface mobilisée.', 2),
    ('fb4080ef-1aa1-5e27-b0b8-0258c76926ae'::uuid, 'd91bf192-a11e-55d4-a213-d8f5750c6248'::uuid, 'Qu’est-ce qu’une agriculture intensive ?', 'mcq', '["Une agriculture qui maximise le rendement par hectare grâce aux intrants et à la mécanisation","Une agriculture sur de grandes surfaces avec peu d’intrants","Une agriculture sans engrais de synthèse","Une agriculture destinée à la seule famille du producteur"]'::jsonb, 0, 'L’agriculture extensive fait l’inverse.', 3),
    ('6d30d7e0-54ee-52aa-9604-ee09d3b2160a'::uuid, 'd91bf192-a11e-55d4-a213-d8f5750c6248'::uuid, 'Qu’exclut l’agriculture biologique ?', 'mcq', '["Les produits de synthèse et les OGM","Toute mécanisation","L’irrigation","La rotation des cultures"]'::jsonb, 0, 'Elle est encadrée par un cahier des charges et une certification.', 4),
    ('a9eae186-6932-556d-bb15-180c8bcae239'::uuid, 'd91bf192-a11e-55d4-a213-d8f5750c6248'::uuid, 'Qu’est-ce que l’eutrophisation ?', 'mcq', '["L’enrichissement excessif d’un milieu aquatique en nutriments, qui asphyxie le milieu","L’assèchement d’une nappe","L’érosion d’un sol","La salinisation d’un champ"]'::jsonb, 0, 'Nitrates et phosphates en sont les principaux responsables.', 5),
    ('cd61b378-28c7-5574-909a-6918085cff44'::uuid, 'd91bf192-a11e-55d4-a213-d8f5750c6248'::uuid, 'Quelle part de la production alimentaire mondiale est perdue ou gaspillée ?', 'mcq', '["Environ un tiers","Environ 5 %","Environ deux tiers","Moins de 1 %"]'::jsonb, 0, 'Réduire ces pertes est un levier majeur.', 6),
    ('75a1f558-5191-50e0-945c-66df426dcc4b'::uuid, 'd91bf192-a11e-55d4-a213-d8f5750c6248'::uuid, 'Un usage répété du même produit phytosanitaire peut sélectionner des ravageurs résistants.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est une application directe de la sélection naturelle.', 7),
    ('36d1ab9a-e207-5011-8daa-0f21127eb135'::uuid, 'd91bf192-a11e-55d4-a213-d8f5750c6248'::uuid, 'La faim dans le monde s’explique-t-elle uniquement par un manque de production ?', 'mcq', '["Non, l’accès et les revenus jouent un rôle majeur","Oui, uniquement","Oui, à cause du climat seul","Non, elle a disparu"]'::jsonb, 0, 'Produire autrement et répartir comptent autant que produire plus.', 8),
    ('1c65a4a0-140b-5947-abcb-529560ad4b71'::uuid, '8ec80c4b-185d-545a-be76-1047d0c9521a'::uuid, 'Quel progrès a levé la principale limite minérale des cultures au XXe siècle ?', 'mcq', '["Les engrais azotés de synthèse","L’irrigation goutte à goutte","La récolte mécanisée","Le stockage réfrigéré"]'::jsonb, 0, 'Ils reposent sur la fixation industrielle de l’azote atmosphérique.', 1),
    ('5875e6b7-c41a-53ed-be62-1bb78e52680c'::uuid, '8ec80c4b-185d-545a-be76-1047d0c9521a'::uuid, 'Quel phénomène littoral résulte d’un excès de nitrates et de phosphates ?', 'mcq', '["Les marées vertes et les zones mortes","L’érosion des falaises","La salinisation des sols","Les remontées de nappe"]'::jsonb, 0, 'C’est une conséquence de l’eutrophisation.', 2),
    ('9da35ddc-f86e-509d-9e8e-1eb82b03f22c'::uuid, '8ec80c4b-185d-545a-be76-1047d0c9521a'::uuid, 'Quel groupe animal connaît un effondrement lié notamment aux pratiques agricoles intensives ?', 'mcq', '["Les insectes pollinisateurs","Les cétacés","Les reptiles marins","Les rongeurs urbains"]'::jsonb, 0, 'Avec les oiseaux des champs.', 3),
    ('24626515-b01c-5134-a052-742f677c3a31'::uuid, '8ec80c4b-185d-545a-be76-1047d0c9521a'::uuid, 'Qu’est-ce que la lutte biologique ?', 'mcq', '["Utiliser un ennemi naturel pour contrôler un ravageur","Traiter avec un pesticide d’origine végétale","Détruire mécaniquement les adventices","Semer des variétés stériles"]'::jsonb, 0, 'Coccinelles contre pucerons, par exemple.', 4),
    ('81c169b7-986e-5b92-9d93-4799ba7fb27c'::uuid, '8ec80c4b-185d-545a-be76-1047d0c9521a'::uuid, 'Que propose la lutte intégrée ?', 'mcq', '["Combiner les méthodes et réserver le traitement chimique au dernier recours","Supprimer tout traitement","Traiter systématiquement par précaution","Remplacer les pesticides par des engrais"]'::jsonb, 0, 'Elle repose sur la surveillance et les seuils d’intervention.', 5),
    ('65f08ff2-6cdf-51e1-ad00-148955d50549'::uuid, '8ec80c4b-185d-545a-be76-1047d0c9521a'::uuid, 'Qu’apporte l’agriculture de précision ?', 'mcq', '["Appliquer un intrant seulement là où il est nécessaire","Augmenter les doses appliquées","Supprimer la mécanisation","Standardiser toutes les parcelles"]'::jsonb, 0, 'Elle s’appuie sur capteurs, cartographie et géolocalisation.', 6),
    ('ac333737-7f6a-5750-a0c5-48ca61e939df'::uuid, '8ec80c4b-185d-545a-be76-1047d0c9521a'::uuid, 'L’usage d’antibiotiques en élevage peut favoriser l’antibiorésistance.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est un enjeu de santé publique reconnu.', 7),
    ('f581d147-79b4-5125-8b30-96d3a299a0eb'::uuid, '8ec80c4b-185d-545a-be76-1047d0c9521a'::uuid, 'Quelles trois exigences une agriculture durable doit-elle concilier ?', 'mcq', '["Nourrir, préserver les milieux, faire vivre les producteurs","Produire, exporter, stocker","Mécaniser, irriguer, fertiliser","Sélectionner, traiter, récolter"]'::jsonb, 0, 'Aucune technique ne dispense de cet arbitrage.', 8),
    ('17b6d8d1-c328-569d-999c-ad1492c85d40'::uuid, '2e7f5e18-78b6-5ca4-9eba-2a144173a1aa'::uuid, 'À quel moment le sexe chromosomique est-il déterminé ?', 'mcq', '["À la fécondation","À la puberté","À la septième semaine de développement","À la naissance"]'::jsonb, 0, 'Le spermatozoïde apporte un X ou un Y.', 1),
    ('ba15df45-5dba-5631-902b-3e7fbf1ae756'::uuid, '2e7f5e18-78b6-5ca4-9eba-2a144173a1aa'::uuid, 'Quel gène déclenche la différenciation des gonades en testicules ?', 'mcq', '["Le gène SRY, porté par le chromosome Y","Le gène X","Le gène de la testostérone","Le gène FSH"]'::jsonb, 0, 'En son absence, les gonades deviennent des ovaires.', 2),
    ('56700b74-b86e-5793-b7b8-cc0129aaef1f'::uuid, '2e7f5e18-78b6-5ca4-9eba-2a144173a1aa'::uuid, 'Comment sont les gonades de l’embryon avant la septième semaine ?', 'mcq', '["Indifférenciées","Déjà des testicules","Déjà des ovaires","Absentes"]'::jsonb, 0, 'Les deux appareils dérivent des mêmes ébauches.', 3),
    ('4425d7cc-deac-5c87-bb9a-27b4533d752d'::uuid, '2e7f5e18-78b6-5ca4-9eba-2a144173a1aa'::uuid, 'Quelle hormone est produite par les testicules fœtaux ?', 'mcq', '["La testostérone","L’insuline","L’adrénaline","La thyroxine"]'::jsonb, 0, 'Avec l’hormone antimüllérienne, elle oriente le développement des conduits.', 4),
    ('e7b3a170-a9b0-5213-9f75-4eeb643ae6fa'::uuid, '2e7f5e18-78b6-5ca4-9eba-2a144173a1aa'::uuid, 'Qu’acquiert-on à la puberté ?', 'mcq', '["La fonction reproductrice et les caractères sexuels secondaires","Le sexe chromosomique","Le sexe gonadique","Les gonades indifférenciées"]'::jsonb, 0, 'La production de gamètes commence à ce moment.', 5),
    ('ad7de68a-d106-5617-b6ff-de5640a47b0b'::uuid, '2e7f5e18-78b6-5ca4-9eba-2a144173a1aa'::uuid, 'Entre quels âges la puberté se produit-elle généralement ?', 'mcq', '["Entre 10 et 16 ans environ","Entre 3 et 6 ans","Entre 18 et 22 ans","À un âge identique pour tous"]'::jsonb, 0, 'La variabilité individuelle est normale.', 6),
    ('fb2dd73d-d34e-596c-a7a1-b1276639ee25'::uuid, '2e7f5e18-78b6-5ca4-9eba-2a144173a1aa'::uuid, 'Le phénotype sexuel se met en place uniquement à la puberté.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il commence avant la naissance et s’achève à la puberté.', 7),
    ('9e809d2b-aa0b-5a2e-8915-6751c6266229'::uuid, '2e7f5e18-78b6-5ca4-9eba-2a144173a1aa'::uuid, 'Qu’est-ce qu’un caractère sexuel secondaire ?', 'mcq', '["Un caractère qui apparaît à la puberté, comme la pilosité ou le développement des seins","Un organe génital présent à la naissance","Un chromosome sexuel","Une hormone"]'::jsonb, 0, 'Les caractères primaires sont les organes génitaux eux-mêmes.', 8),
    ('e0ea389f-98b8-52a6-b17d-e60a497f066a'::uuid, 'dbecdf2f-8460-5177-a510-e378bccab3cb'::uuid, 'Quel organe contrôle les réponses sexuelles réflexes ?', 'mcq', '["La moelle épinière","Le cortex cérébral","L’hypophyse","Le cervelet"]'::jsonb, 0, 'Ces réflexes fonctionnent sans décision consciente.', 1),
    ('af34b449-c4c0-5c97-994a-cf1fff6868fd'::uuid, 'dbecdf2f-8460-5177-a510-e378bccab3cb'::uuid, 'Quel neurotransmetteur est associé au système de récompense ?', 'mcq', '["La dopamine","L’insuline","La testostérone","L’hémoglobine"]'::jsonb, 0, 'Il associe un comportement à une sensation de plaisir.', 2),
    ('5f7a5dea-8406-5da3-8862-1734584c3c42'::uuid, 'dbecdf2f-8460-5177-a510-e378bccab3cb'::uuid, 'Quel rôle joue le cortex dans la sexualité humaine ?', 'mcq', '["Il intègre mémoire, imaginaire, émotions et relation à l’autre","Il déclenche les réflexes","Il produit les hormones sexuelles","Il fabrique les gamètes"]'::jsonb, 0, 'Il module les réponses automatiques.', 3),
    ('2a16bcdc-a3ea-5592-a632-8cd080147f89'::uuid, 'dbecdf2f-8460-5177-a510-e378bccab3cb'::uuid, 'Qu’est-ce qui distingue la sexualité humaine de celle de nombreuses espèces ?', 'mcq', '["Elle est largement dissociée de la seule reproduction et dépend du contexte","Elle est uniquement hormonale","Elle est saisonnière","Elle ne fait pas intervenir le système nerveux"]'::jsonb, 0, 'Apprentissages, culture et relations y jouent un rôle majeur.', 4),
    ('f45625d9-7b3a-5e25-81b9-0f63287b26cd'::uuid, 'dbecdf2f-8460-5177-a510-e378bccab3cb'::uuid, 'Quelles caractéristiques doit avoir un consentement ?', 'mcq', '["Libre, éclairé, révocable à tout moment","Donné une fois pour toutes","Implicite dans un couple","Valable pour toute la soirée"]'::jsonb, 0, 'Il ne se présume jamais.', 5),
    ('d625890f-0590-51ab-83af-dde8e63cfb4c'::uuid, 'dbecdf2f-8460-5177-a510-e378bccab3cb'::uuid, 'Que prévoit le droit face à une atteinte sexuelle imposée ?', 'mcq', '["Elle est sanctionnée pénalement","Elle relève du seul règlement intérieur","Elle est tolérée entre majeurs","Elle ne concerne que les mineurs"]'::jsonb, 0, 'Le harcèlement sexuel est également puni.', 6),
    ('0f2a5665-f4bd-540f-b87e-a44a097143de'::uuid, 'dbecdf2f-8460-5177-a510-e378bccab3cb'::uuid, 'La pornographie constitue une source fiable d’information sur la sexualité.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ce sont des productions commerciales, éloignées de la réalité des relations.', 7),
    ('1d368582-d38f-5225-ae36-075ade27aec8'::uuid, 'dbecdf2f-8460-5177-a510-e378bccab3cb'::uuid, 'Vers qui se tourner pour une information fiable sur la santé sexuelle ?', 'mcq', '["L’infirmerie scolaire, un médecin ou un centre de santé sexuelle","Les réseaux sociaux","Les forums anonymes","La publicité"]'::jsonb, 0, 'Des structures publiques et gratuites existent.', 8),
    ('0d337a9d-cc25-5d2b-8dc5-e8a140176328'::uuid, '54e33e84-6d7e-56cf-b5f1-7520fafc6879'::uuid, 'Qu’est-ce qu’une hormone ?', 'mcq', '["Une substance produite par une glande, transportée par le sang, agissant sur des cellules cibles","Un message nerveux rapide","Une enzyme digestive","Un nutriment"]'::jsonb, 0, 'Seules les cellules portant le récepteur y répondent.', 1),
    ('b28bbb02-6c3a-5dce-9004-14902378100f'::uuid, '54e33e84-6d7e-56cf-b5f1-7520fafc6879'::uuid, 'Quelles hormones l’hypophyse sécrète-t-elle pour commander les gonades ?', 'mcq', '["FSH et LH","Testostérone et œstrogènes","Insuline et glucagon","Adrénaline et cortisol"]'::jsonb, 0, 'Ce sont les gonadostimulines.', 2),
    ('8a4676ca-ad90-5f3b-8f38-1077e7ce9921'::uuid, '54e33e84-6d7e-56cf-b5f1-7520fafc6879'::uuid, 'Quel événement le pic de LH déclenche-t-il chez la femme ?', 'mcq', '["L’ovulation","Les règles","La nidation","La ménopause"]'::jsonb, 0, 'Il survient vers le 14e jour d’un cycle de 28 jours.', 3),
    ('1942b8ac-c2a6-5216-8931-08f5c33ab165'::uuid, '54e33e84-6d7e-56cf-b5f1-7520fafc6879'::uuid, 'Quelle hormone prépare la muqueuse utérine après l’ovulation ?', 'mcq', '["La progestérone","La FSH","La testostérone","L’insuline"]'::jsonb, 0, 'Avec les œstrogènes, elle rend la muqueuse apte à l’implantation.', 4),
    ('c40b17f6-4b94-5d8f-bad5-8bffbf483438'::uuid, '54e33e84-6d7e-56cf-b5f1-7520fafc6879'::uuid, 'Qu’est-ce qu’un rétrocontrôle négatif ?', 'mcq', '["Une hormone qui freine en retour la structure qui l’a fait produire","Une hormone qui amplifie sa propre production","Un message nerveux inhibiteur","Une réaction allergique"]'::jsonb, 0, 'Il stabilise les taux hormonaux.', 5),
    ('479d9ac9-e1f4-5ec4-87f3-e7301530430b'::uuid, '54e33e84-6d7e-56cf-b5f1-7520fafc6879'::uuid, 'Que provoque la chute hormonale en fin de cycle, sans fécondation ?', 'mcq', '["L’élimination de la muqueuse utérine, soit les règles","Une nouvelle ovulation immédiate","La nidation","L’arrêt définitif du cycle"]'::jsonb, 0, 'Un nouveau cycle démarre alors.', 6),
    ('8ffea851-5299-5717-a36e-23ea7c9c5c7b'::uuid, '54e33e84-6d7e-56cf-b5f1-7520fafc6879'::uuid, 'Le préservatif est le seul moyen de contraception protégeant aussi des IST.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La contraception hormonale ne protège pas des infections.', 7),
    ('8b32cb5b-3d54-59a1-acbc-7d1da2e38209'::uuid, '54e33e84-6d7e-56cf-b5f1-7520fafc6879'::uuid, 'Comment agit une contraception hormonale de type pilule combinée ?', 'mcq', '["Elle bloque l’ovulation par rétrocontrôle et modifie la glaire cervicale","Elle détruit les spermatozoïdes","Elle empêche la formation de la muqueuse utérine uniquement","Elle agit après la fécondation"]'::jsonb, 0, 'Elle utilise le mécanisme hormonal naturel.', 8),
    ('388d8210-3af4-53f7-bcf3-17e7b93ad005'::uuid, 'd88d1901-226d-5075-ac92-f6299d98cb7f'::uuid, 'Qu’est-ce qu’un agent pathogène ?', 'mcq', '["Un micro-organisme capable de provoquer une maladie","Un organisme utile à la digestion","Un vecteur animal","Un vaccin atténué"]'::jsonb, 0, 'Bactéries, virus, champignons et protozoaires en font partie.', 1),
    ('4b0519d5-f2d1-552e-994a-cb51d71f233b'::uuid, 'd88d1901-226d-5075-ac92-f6299d98cb7f'::uuid, 'Qu’est-ce qui distingue un virus d’une bactérie ?', 'mcq', '["Le virus n’est pas une cellule et doit parasiter une cellule hôte","Le virus est plus gros","La bactérie n’a pas d’ADN","La bactérie ne se multiplie pas"]'::jsonb, 0, 'La bactérie est une cellule procaryote autonome.', 2),
    ('161b04ae-64aa-53ce-bab4-82767a5ac21e'::uuid, 'd88d1901-226d-5075-ac92-f6299d98cb7f'::uuid, 'Quel agent est responsable du paludisme ?', 'mcq', '["Un protozoaire du genre Plasmodium","Une bactérie","Un virus","Un champignon"]'::jsonb, 0, 'Il est transmis par un moustique du genre Anopheles.', 3),
    ('245c50ef-ba04-52c0-9089-f932f2f946b0'::uuid, 'd88d1901-226d-5075-ac92-f6299d98cb7f'::uuid, 'Quelles maladies le moustique tigre peut-il transmettre ?', 'mcq', '["La dengue, le chikungunya et le Zika","La tuberculose et le tétanos","La maladie de Lyme","La grippe"]'::jsonb, 0, 'Aedes albopictus est un vecteur en expansion.', 4),
    ('137d904a-f888-54d4-9d2e-9b0b7c2c31de'::uuid, 'd88d1901-226d-5075-ac92-f6299d98cb7f'::uuid, 'Quel animal transmet la maladie de Lyme ?', 'mcq', '["La tique","Le moustique","La puce","Le rat"]'::jsonb, 0, 'L’agent est une bactérie du genre Borrelia.', 5),
    ('01b7439c-cab1-5768-b679-f64d72937780'::uuid, 'd88d1901-226d-5075-ac92-f6299d98cb7f'::uuid, 'Qu’est-ce qu’une transmission vectorielle ?', 'mcq', '["La transmission par un animal qui transporte l’agent pathogène","La transmission par l’eau","La transmission par contact direct","La transmission par voie aérienne"]'::jsonb, 0, 'Le parasite accomplit souvent une partie de son cycle dans le vecteur.', 6),
    ('5ad4e551-2968-561e-9c2e-78e6df5a6948'::uuid, 'd88d1901-226d-5075-ac92-f6299d98cb7f'::uuid, 'Le réchauffement climatique modifie la répartition des maladies à vecteur.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le moustique tigre s’est installé dans une grande partie de la France.', 7),
    ('eff97dbb-3f56-5ecd-87cd-ca88143b002f'::uuid, 'd88d1901-226d-5075-ac92-f6299d98cb7f'::uuid, 'Quel geste simple limite la prolifération du moustique tigre ?', 'mcq', '["Éliminer les eaux stagnantes autour des habitations","Aérer les pièces","Se laver les mains plus souvent","Faire bouillir l’eau de boisson"]'::jsonb, 0, 'Ses larves se développent dans de très petits volumes d’eau.', 8),
    ('e4443a41-27d9-5da9-9ff4-023778de7041'::uuid, 'c83a4d28-2012-58c5-b0eb-a9f050ea8d42'::uuid, 'Qu’est-ce que le mutualisme ?', 'mcq', '["Une association bénéfique aux deux partenaires","Une association bénéfique à un seul, sans nuire à l’autre","Une association nuisible à l’un des deux","Une absence de relation"]'::jsonb, 0, 'Le commensalisme ne profite qu’à l’un, sans nuire.', 1),
    ('e6f826b5-035b-5557-b62f-5c48b307262e'::uuid, 'c83a4d28-2012-58c5-b0eb-a9f050ea8d42'::uuid, 'Que gagnent les légumineuses associées aux Rhizobium ?', 'mcq', '["De l’azote, fixé à partir de l’air par la bactérie","Du sucre","De l’eau","De la lumière"]'::jsonb, 0, 'La bactérie reçoit en échange des sucres de la plante.', 2),
    ('80c7f69f-de00-5333-a538-fdffabf1fde9'::uuid, 'c83a4d28-2012-58c5-b0eb-a9f050ea8d42'::uuid, 'Qu’est-ce qu’une mycorhize ?', 'mcq', '["Une association entre les racines d’une plante et un champignon","Une maladie fongique","Un organe de réserve","Une bactérie du sol"]'::jsonb, 0, 'Elle améliore l’absorption d’eau et de minéraux.', 3),
    ('728144de-21d7-5e82-9688-0fd8daa5dbb1'::uuid, 'c83a4d28-2012-58c5-b0eb-a9f050ea8d42'::uuid, 'Qu’est-ce que le microbiote humain ?', 'mcq', '["L’ensemble des micro-organismes vivant sur et dans le corps","L’ensemble des cellules humaines","Les agents pathogènes du corps","Les cellules immunitaires"]'::jsonb, 0, 'Il occupe l’intestin, la peau, la bouche, les muqueuses.', 4),
    ('56898546-8795-50f1-aecd-65363d298208'::uuid, 'c83a4d28-2012-58c5-b0eb-a9f050ea8d42'::uuid, 'Quand le microbiote se met-il en place ?', 'mcq', '["Dès la naissance, puis il se diversifie les premières années","À la puberté","À l’âge adulte","Avant la naissance uniquement"]'::jsonb, 0, 'Mode d’accouchement, allaitement et environnement l’influencent.', 5),
    ('1957af52-b752-5e2d-8547-9c2105834487'::uuid, 'c83a4d28-2012-58c5-b0eb-a9f050ea8d42'::uuid, 'Qu’est-ce que l’effet barrière du microbiote ?', 'mcq', '["Occuper la place et empêcher l’installation d’agents pathogènes","Produire des anticorps","Détruire les cellules infectées","Filtrer les toxines du sang"]'::jsonb, 0, 'C’est une protection par occupation du milieu.', 6),
    ('e28420d0-ea88-5af3-9a08-fddcf06cc7c0'::uuid, 'c83a4d28-2012-58c5-b0eb-a9f050ea8d42'::uuid, 'Chaque être humain possède un microbiote qui lui est propre.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Sa composition dépend de l’histoire et du mode de vie de chacun.', 7),
    ('3738589b-eb46-574b-bf32-5aed553a6af1'::uuid, 'c83a4d28-2012-58c5-b0eb-a9f050ea8d42'::uuid, 'Qu’est-ce qu’un micro-organisme opportuniste ?', 'mcq', '["Un micro-organisme habituellement inoffensif qui devient pathogène quand les défenses sont affaiblies","Un agent toujours pathogène","Un virus mutant","Une bactérie résistante aux antibiotiques"]'::jsonb, 0, 'Le rôle d’un micro-organisme dépend du contexte.', 8),
    ('bdbdf2ec-d251-5b86-9019-44d0f76d67c0'::uuid, 'a999ff85-31c2-5491-bda6-0aeac20bd271'::uuid, 'Où se concentre l’essentiel du microbiote intestinal ?', 'mcq', '["Dans le côlon","Dans l’estomac","Dans l’œsophage","Dans le foie"]'::jsonb, 0, 'Il y compte plusieurs centaines d’espèces bactériennes.', 1),
    ('835e6a99-527b-5f53-9a75-261976852989'::uuid, 'a999ff85-31c2-5491-bda6-0aeac20bd271'::uuid, 'Que produit le microbiote en dégradant les fibres alimentaires ?', 'mcq', '["Des acides gras à chaîne courte utilisés par la paroi intestinale","Des protéines musculaires","De l’insuline","Des anticorps"]'::jsonb, 0, 'Nos propres enzymes ne savent pas dégrader ces fibres.', 2),
    ('8ee8e787-25a0-5ba6-bdd6-63de7792e644'::uuid, 'a999ff85-31c2-5491-bda6-0aeac20bd271'::uuid, 'Quelle vitamine le microbiote intestinal contribue-t-il à synthétiser ?', 'mcq', '["La vitamine K","La vitamine C","La vitamine D","La vitamine A"]'::jsonb, 0, 'Ainsi que plusieurs vitamines du groupe B.', 3),
    ('2795f1bf-7b83-537c-a668-00db1b00aa86'::uuid, 'a999ff85-31c2-5491-bda6-0aeac20bd271'::uuid, 'Qu’est-ce qu’une dysbiose ?', 'mcq', '["Un déséquilibre durable de la composition du microbiote","Une infection virale de l’intestin","Une allergie alimentaire","Une carence en fer"]'::jsonb, 0, 'Elle est associée à plusieurs pathologies chroniques.', 4),
    ('d6a8a79c-75b3-5eb2-94f7-5460472fc7ae'::uuid, 'a999ff85-31c2-5491-bda6-0aeac20bd271'::uuid, 'Quel traitement perturbe fortement le microbiote intestinal ?', 'mcq', '["Les antibiotiques","Les antalgiques","Les vaccins","Les antihistaminiques"]'::jsonb, 0, 'Ils détruisent aussi les bactéries utiles.', 5),
    ('6eee028f-383d-5f7b-807a-31887ac12a91'::uuid, 'a999ff85-31c2-5491-bda6-0aeac20bd271'::uuid, 'Un antibiotique est-il efficace contre un virus ?', 'mcq', '["Non, il n’agit que sur les bactéries","Oui, sur tous les microbes","Oui, s’il est pris tôt","Seulement contre la grippe"]'::jsonb, 0, 'D’où l’inutilité d’en prendre contre un rhume.', 6),
    ('562e2289-256f-52b7-a72c-6a845c101af6'::uuid, 'a999ff85-31c2-5491-bda6-0aeac20bd271'::uuid, 'Quelle différence entre probiotiques et prébiotiques ?', 'mcq', '["Les probiotiques apportent des micro-organismes vivants, les prébiotiques les nourrissent","Les probiotiques sont des médicaments, les prébiotiques des aliments","Ils sont synonymes","Les prébiotiques détruisent les bactéries"]'::jsonb, 0, 'Les fibres sont l’exemple type des prébiotiques.', 7),
    ('32a54a9b-20ec-5c48-b9fc-9493d26cd964'::uuid, 'a999ff85-31c2-5491-bda6-0aeac20bd271'::uuid, 'La transplantation de microbiote fécal est utilisée contre certaines infections récidivantes.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Notamment contre Clostridioides difficile, quand les antibiotiques échouent.', 8)
  ) AS v(id, quiz_id, question, kind, options, correct_index, explanation, position)
-- Le quiz doit exister : si le NOT EXISTS ci-dessus a écarté un quiz (une
-- leçon en avait déjà un), ses questions ne partent pas dans le vide.
 WHERE EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.id = v.quiz_id)
ON CONFLICT (id) DO NOTHING;

-- 5. Sonde finale ----------------------------------------------------------
DO $$
DECLARE
  n_vides integer;
  n_chap  integer;
BEGIN
  SELECT count(*) INTO n_chap FROM public.chapters c
   JOIN public.subjects s ON s.id = c.subject_id
   WHERE s.slug IN ('svt');
  SELECT count(*) INTO n_vides FROM public.subjects s
   WHERE s.slug IN ('svt')
     AND NOT EXISTS (SELECT 1 FROM public.chapters c WHERE c.subject_id = s.id);
  IF n_vides > 0 THEN
    RAISE EXCEPTION 'Migration 285 incomplète : % matiere(s) encore sans chapitre', n_vides;
  END IF;
  RAISE NOTICE 'Migration 285 OK : % chapitres sur les matieres visees.', n_chap;
END $$;
